#!/usr/bin/env python3
"""The JSON catalog is the balance source; regenerate Java and the reference after editing."""
import json,pathlib,csv,io
ROOT=pathlib.Path(__file__).resolve().parents[1]
GAME=json.loads((ROOT/'tools/modifier-gameplay.json').read_text(encoding="utf-8"))
ROWS=json.loads((ROOT/'tools/pickaxe-modifiers.json').read_text(encoding="utf-8"))
JAVA=ROOT/'src/main/java/com/example/examplemod'
def q(s):return json.dumps(s)
def generate():
 assert len(ROWS)==120 and sum(not r['exclusive'] for r in ROWS)==100
 assert sum(r['exclusive'] and r['influence']=='NETHER' for r in ROWS)==10
 assert sum(r['exclusive'] and r['influence']=='END' for r in ROWS)==10
 assert sum(r['utility'] for r in ROWS)==12
 lines=['package com.example.examplemod;','import java.util.Locale;','/** Generated by tools/generate_pickaxe_catalog.py. Stable IDs must never be renamed. */','public enum PickaxeTrait {']
 for i,r in enumerate(ROWS):lines.append('    %s(%s,%s,Unit.%s,%s,%s,%s,%s,Growth.%s,Family.%s)%s'%(r['key'],q(r['id']),q(r['label']),r['unit'],r['cap'],r['power'],str(r['utility']).lower(),q(r['milestones']),r['growth'],r['family'],';' if i==len(ROWS)-1 else ','))
 lines+=['    public enum Unit { PERCENT, LEVEL, BLOCKS, POINTS, PERK }','    public enum Growth { NUMERIC, MILESTONE }','    public enum Family { '+', '.join(sorted({r['family'] for r in ROWS}))+' }', '''    public final String id,label,milestones;
    public final Unit unit; public final double cap,power; public final boolean utility;
    public final Growth growth; public final Family family;
    PickaxeTrait(String id,String label,Unit unit,double cap,double power,boolean utility,String milestones,Growth growth,Family family){this.id="examplemod:"+id;this.label=label;this.unit=unit;this.cap=cap;this.power=power;this.utility=utility;this.milestones=milestones;this.growth=growth;this.family=family;}
    public String format(double value){return switch(unit){case PERCENT->String.format(Locale.ROOT,"%.1f%%",value*100);case LEVEL->String.format(Locale.ROOT,"%.2f levels",value);case BLOCKS->String.format(Locale.ROOT,"%.2f blocks",value);case POINTS->String.format(Locale.ROOT,"%.2f",value);case PERK->"milestone perk";};}
    public static PickaxeTrait byId(String id){for(var trait:values())if(trait.id.equals(id))return trait;return null;}
}''']
 yield JAVA/'PickaxeTrait.java','\n'.join(lines)+'\n'
 lines=['package com.example.examplemod;','import java.util.*;','import static com.example.examplemod.PickaxeTrait.*;','/** Generated balance definitions. Edit tools/pickaxe-modifiers.json, then regenerate. */','final class ModifierDefinitions {','    static final Map<PickaxeTrait,ArtifactModifierCatalog.Spec> SPECS=specs();','    static Map<PickaxeTrait,ArtifactModifierCatalog.Spec> specs(){','        var m=new EnumMap<PickaxeTrait,ArtifactModifierCatalog.Spec>(PickaxeTrait.class);']
 for r in ROWS:
  ts=', '.join('new ModifierTier("t%d",%d,%s,%s,List.of(%s))'%(t['rank'],t['rank'],t['minimum'],t['maximum'],','.join(map(str,t['weights']))) for t in r['tiers'])
  lines.append('        m.put(%s,new ArtifactModifierCatalog.Spec(%d,List.of(%s),ModifierInfluence.%s,%s));'%(r['key'],r['minimumRarity'],ts,r['influence'],str(r['exclusive']).lower()))
 lines+=['        return Map.copyOf(m);','    }','    static int weight(PickaxeTrait trait){return switch(trait){']
 for r in ROWS:lines.append('        case %s -> %d;'%(r['key'],r['weight']))
 lines+=['    };}','    static AscensionResources.Binding resource(PickaxeTrait trait){return switch(trait){']
 for r in ROWS:lines.append('        case %s -> new AscensionResources.Binding(net.minecraft.world.item.Items.%s,%d);'%(r['key'],r['resource'],1 if r['key']=='REACH' else 2))
 lines+=['    };}','    private ModifierDefinitions(){}','}']
 yield JAVA/'ModifierDefinitions.java','\n'.join(lines)+'\n'
 header="# Reconstructed pickaxe modifier reference\n\nThe catalog contains **100 ordinary modifiers**, including 12 universal handle/connector rolls, plus **10 Nether-only and 10 End-only modifiers**. Edit `tools/pickaxe-modifiers.json` and `tools/modifier-gameplay.json`, then run `python3 tools/generate_pickaxe_catalog.py`. CI checks generated Java, descriptions and this reference.\n\n## A tool worth reconstructing\n\nA reconstructed pickaxe receives an innate mining multiplier of **1 + 2 × average quality of its three head pieces**: 1× at 0%, 2× at 50%, 3× at 100%, and 3.4× at 120%. This multiplies the native mining speed, including Efficiency and Haste; native water/airborne penalties still apply. It does not replace or remove enchantments. At 100% quality, a Diamond-speed restored pickaxe with Efficiency V has a 102 base speed versus 35 for a Netherite Efficiency V pickaxe, before its rolled modifiers. A strong unenchanted speed build can also beat that vanilla benchmark. Actual break times still depend on hardness, correct tool, penalties and the one-tick minimum.\n\nFortune rolls add to the native enchantment up to **Fortune X**, preserving an existing stronger enchantment. This pass does not change artifact acquisition/drop chances. Existing recovered parts keep their original seeds, raw rolls, tiers, grades, quality, locks, influence and corruption; the stronger effect conversion applies to old parts too. New high-rarity rolls favor strong tiers and more modifier attempts without guaranteeing a particular result.\n\nRarity modifier-count attempts: Common `[1]`, Uncommon `[1,.35]`, Rare `[1,.8,.35]`, Epic `[1,.95,.7]`, Legendary `[1,.99,.9,.6]`, Unique `[1,.999,.97,.85]`. A family is selected by its weight first, then a tier by that rarity's tier weights, then a uniform value inside its band. T1 is strongest. The six weights in each band below are Common/Uncommon/Rare/Epic/Legendary/Unique. They are relative weights, not fixed probabilities. Matching influence receives 6× family weight; foreign influence is excluded. Influence is permanent and can only be applied once at the Influencer. No influence label is added to ordinary component tooltips.\n\nHandles/connectors use only the twelve **Universal** modifiers, which work on all seven reconstructed tool types. Head pieces use the mining pool. Saved old mining rolls on handles still work on pickaxes, but do not affect other tools.\n\n## Quality and growth\n\nNumeric contribution = `raw roll × effect conversion × quality/100 × (1 + ascensions × grade bonus + selected-level awards × level bonus)`, capped after summing contributions. The displayed bands below include the effect conversion; saved raw rolls remain stable. Quality is 0–120%; a zero-quality piece grants no modifier effects or milestone stages. Each ordinary level selects 1–3 positive numeric contributions for a small increment. Perks advance by ascension milestones instead.\n\n| Grade | Per ascension, relative to base | Per selected level | Perk ascension thresholds |\n|---|---:|---:|---|\n| F | +6% | +0.05% | 4 / 7 / 10 |\n| D | +10% | +0.10% | 4 / 7 / 10 |\n| C | +15% | +0.15% | 3 / 6 / 9 |\n| B | +22% | +0.25% | 3 / 6 / 9 |\n| A | +32% | +0.35% | 2 / 5 / 8 |\n| S | +45% | +0.50% | 2 / 5 / 8 |\n\nA perk activates with its combined quality-adjusted chance, capped at 100%, and uses the strongest positive-quality copy's stage. Stage values below mean stage 0 / 1 / 2 / 3. Cooldowns are per tool. Every reconstructed pickaxe has a **200 resonance** capacity; primary mining and holding the tool generate quality-scaled core charge, so consumers function without requiring another lucky generator roll. Dedicated generators enable more frequent combined use.\n\nCrouch to enable area mining. All area effects share at most **64 extra native breaks** per primary break within a loaded 16-block range. No recursion, extra tool XP, primary bonus drops or charge generation from secondary breaks. Secondary loot still uses native Fortune, Silk, furnace recipes and the five material conversions. Block entities, claims, canceled events, unbreakable blocks, wrong tools, unloaded chunks and the world border are respected. Utility placement consumes owned materials only after a successful cancellable placement. Silk disables duplication, bonus drops and furnace conversions.\n\nUse the **Ancient Field Guide** for searchable modifier definitions, stage effects, growth, caps and ascension materials. Actual effective values, grades, tiers and quality remain on item tooltips. Hold Shift and scroll to browse tool modifier pages. The book never reads or rolls unopened artifacts or reveals hidden ancient choices.\n\n## Complete catalog\n\n| # | ID / name | Pool; minimum artifact rarity; family weight | Effect and implementation | Effective tiers at 100% quality `[C,U,R,E,L,X weights]` | Growth / stage effects | Combined cap | Ascension material |\n|---|---|---|---|---|---|---:|---|\n"
 rarity=['Common','Uncommon','Rare','Epic','Legendary','Unique']
 docs=[header];out=io.StringIO(); writer=csv.writer(out,lineterminator="\n");writer.writerow(['id','name','pool','minimum_rarity','family_weight','effect','handler','value_tiers','growth','milestones','cap','unit','effect_conversion','ascension_material'])
 for i,r in enumerate(ROWS,1):
  pool='Universal' if r['utility'] else r['influence']+' exclusive' if r['exclusive'] else 'Pickaxe head'+(' ('+r['influence']+' tag)' if r['influence']!='NONE' else '')
  bands='; '.join('T%d %g–%g [%s]'%(t['rank'],t['minimum'],t['maximum'],','.join(map(str,t['weights']))) for t in r['tiers'])
  handler={'UTILITY':'SharedToolEffects','ATTRIBUTE':'PickaxeModifiers','SPEED':'PickaxeEvents / MiningConditions','LOOT':'MiningLootEffects','COLLECTION':'PickaxeEvents / MiningCollectionEffects','TRANSFORM':'MiningLootEffects','AREA':'MiningAreaEffects','PLACE':'MiningPlacementEffects','STATUS':'MiningStatusEffects','CHARGE':'MiningChargeEffects','PROGRESSION':'RestoredAncientPickaxe'}[r['family']]
  if r['key'] in ['DURABILITY','RESERVE']:handler='PickaxeModifiers'
  display=lambda v:('%g%%'%(v*100)) if r['unit']=='PERCENT' else ('%g'%v)
  shown_bands='; '.join('T%d %s–%s [%s]'%(t['rank'],display(t['minimum']*r['power']),display(t['maximum']*r['power']),','.join(map(str,t['weights']))) for t in r['tiers'])
  docs.append('| %d | `%s` **%s** | %s; %s; %d | %s `%s` | %s | %s%s | %s %s | %s |\n'%(i,r['id'],r['label'],pool,rarity[r['minimumRarity']],r['weight'],r['description'],handler,shown_bands,r['growth'].title(),': '+r['milestones'] if r['milestones'] else '',display(r['cap']),'' if r['unit']=='PERCENT' else r['unit'].lower(),r['resource'].lower()))
  writer.writerow([r['id'],r['label'],pool,rarity[r['minimumRarity']],r['weight'],r['description'],handler,bands,r['growth'],r['milestones'],r['cap'],r['unit'],r['power'],r['resource'].lower()])
 docs.append("\nNative enchantments and area breaking remain native. Full inventories retain exact drops. Direct XP siphoning also repairs the tool; XP Condenser deliberately increases released banked XP. Core generation precedes consumers; later consumers may wait when resonance is exhausted. No player-targeting pulses, arbitrary thrown-item vacuuming or permanent drop invulnerability.\n")
 yield ROOT/'docs/PICKAXE_MODIFIERS.md',''.join(docs)
 yield ROOT/'docs/PICKAXE_MODIFIERS.csv',out.getvalue()
 # All live effect parameters and their explanations come from the same reviewed data.
 lines=['package com.example.examplemod;','/** Generated global balance; edit tools/modifier-gameplay.json. */','public final class ModifierGameplay {']
 for key,val in GAME.items():
  if isinstance(val,(int,float)):lines.append('    public static final double %s=%s;'%(key.upper(),val))
 lines.append('    public static final double[][] RARITY_CHANCES={'+','.join('{'+','.join(map(str,row))+'}' for row in GAME['rarity_chances'])+'};')
 for grade,values in GAME['growth'].items():
  for name,val in zip(['ASCENSION','LEVEL'],values):lines.append('    public static final double %s_%s=%s;'%(grade,name,val))
 lines+=['    private ModifierGameplay(){}','}']
 yield JAVA/'ModifierGameplay.java','\n'.join(lines)+'\n'
 keys=sorted({key for r in ROWS for key in r['rules']})
 lines=['package com.example.examplemod;','import java.util.*;','/** Generated stage parameters; the inspector uses this exact same data. */','public final class ModifierTuning {','    public enum Key { '+', '.join(keys)+' }','    private static final Map<PickaxeTrait,Map<Key,List<Double>>> RULES=rules();','    private static Map<PickaxeTrait,Map<Key,List<Double>>> rules(){','        var m=new EnumMap<PickaxeTrait,Map<Key,List<Double>>>(PickaxeTrait.class);']
 for r in ROWS:
  if r['rules']:lines.append('        m.put(PickaxeTrait.%s,Map.ofEntries(%s));'%(r['key'],','.join('Map.entry(Key.%s,List.of(%s))'%(key,','.join(str(float(x)) for x in vals)) for key,vals in r['rules'].items())))
 lines+=['        return Map.copyOf(m);','    }','    public static Map<Key,List<Double>> rules(PickaxeTrait trait){return RULES.getOrDefault(trait,Map.of());}','    public static double value(PickaxeTrait trait,Key key,int stage){var values=rules(trait).get(key);return values==null?0:values.get(Math.clamp(stage,0,3));}','    public static int integer(PickaxeTrait trait,Key key,int stage){return (int)value(trait,key,stage);}','    private ModifierTuning(){}','}']
 yield JAVA/'ModifierTuning.java','\n'.join(lines)+'\n'
 lines=['package com.example.examplemod;','/** Generated player-facing descriptions. No hidden rolls are exposed. */','public final class ModifierDescriptions {','    public static String description(PickaxeTrait trait){return switch(trait){']
 for r in ROWS:lines.append('        case %s -> %s;'%(r['key'],q(r['description'])))
 lines+=['    };}','    private ModifierDescriptions(){}','}']
 yield JAVA/'ModifierDescriptions.java','\n'.join(lines)+'\n'
 review=['# Modifier reward review\n\nEvery one of the 120 modifiers was reviewed. Saved rolls and acquisition chances remain unchanged. Bands in the reference include the new effect conversion. These are initial generous rewards; caps and bounded effects still prevent recursive or unbounded resource generation.\n\n| Modifier | Effect conversion | Combined cap | Review and reason |\n|---|---:|---:|---|\n']
 for r in ROWS:review.append('| **%s** | %s× saved base | %s | %s |\n'%(r['label'],r['power'],r['cap'],r['review']))
 yield ROOT/'docs/MODIFIER_REWARD_REVIEW.md',''.join(review)
 chapters=json.loads((ROOT/'tools/field-guide.json').read_text(encoding="utf-8"))
 for c in chapters:
  c['paragraphs']=list(c['paragraphs'])
  for recipe_id in c.get('recipes',[]):
   recipe=json.loads((ROOT/'src/main/resources/data/examplemod/recipe'/f'{recipe_id}.json').read_text(encoding="utf-8"))
   readable=lambda key:('any ' if key.startswith('#') else '')+key.lstrip('#').split(':')[-1].replace('_',' ')
   title=recipe_id.replace('_',' ')
   if recipe['type']=='minecraft:crafting_shaped':
    pattern=' / '.join(row.replace(' ','.') for row in recipe['pattern'])
    legend='; '.join(key+' = '+readable(value) for key,value in recipe['key'].items())
    c['paragraphs'].append('Craft '+title+': grid rows '+pattern+'. A dot means an empty cell. '+legend+'.')
   elif recipe['type']=='minecraft:crafting_shapeless':c['paragraphs'].append('Craft '+title+': '+' + '.join(readable(value) for value in recipe['ingredients'])+', in any arrangement.')
   else:raise ValueError('Unsupported guide recipe: '+recipe_id)
 ids={r['id'] for r in chapters}|{'examplemod:'+r['id'] for r in ROWS}
 assert all(len(c['links'])<=4 for c in chapters),"Guide related links must fit their page"
 assert len(ids)==len(chapters)+len(ROWS),"Guide entry IDs must be unique"
 assert all(link in ids for chapter in chapters for link in chapter['links']),"Broken guidebook cross-reference"
 lines=['package com.example.examplemod;','import java.util.List;','/** Generated from tools/field-guide.json. */','final class FieldGuideChapters {','    static List<FieldGuide.Entry> entries(){return List.of(']
 for i,c in enumerate(chapters):lines.append('        new FieldGuide.Entry(%s,FieldGuide.Category.%s,FieldGuide.Group.ALL,%s,%s,List.of(%s),List.of(%s),%s)%s'%(q(c['id']),c['category'],q(c['title']),q(c['icon']),','.join(q(p) for p in c['paragraphs']),','.join(q(p) for p in c['links']),q(c['keywords']),',' if i<len(chapters)-1 else ''))
 lines+=['    );}','    private FieldGuideChapters(){}','}']
 yield JAVA/'FieldGuideChapters.java','\n'.join(lines)+'\n'
 guide=['# Ancient Field Guide\n\nCraft a normal book and one paper together, or find the guide in the creative tab. Right-click to read. Home opens an illustrated contents page. Pick a category, then an article. Modifiers has a separate topic index. Search always looks through the entire guide, including article text, modifier IDs and keywords. Clear search with its X. Read across both pages; arrows and mouse wheel turn reading spreads or list pages. Related links sit below articles. Back restores the previous view and search; Escape closes the book. Your place is remembered for the play session. Native Minecraft buttons support primary mouse clicks and keyboard focus/activation.\n\nActual rolled values, scaling grades, value tiers and quality remain on item tooltips. Hold Shift and scroll over a reconstructed tool tooltip to browse its modifier pages. The book explains definitions and systems without reading or changing an item.\n\nThe Appraisal Table and its remaining compatibility registrations are removed.\n\n## Design references\n\nThe category-first contents and page navigation were informed by [Lexica Botania](https://botaniamod.net/lexicon.html) and [Materials and You](https://slimeknights.github.io/docs/books/1.20/materials-and-you/). The book interface and 32-pixel teal/brass field-guide icon are original assets; no dependency or copied book textures are required.\n\n## Contents\n\n']
 for c in chapters:guide.append('- [%s](#%s) — %s\n'%(c['title'],c['id'].replace('_','-'),c['category'].title()))
 guide.append('\n- All 120 modifiers: generated in the in-game Modifiers category from the same definitions and tuning values used by gameplay. See also [the complete modifier table](PICKAXE_MODIFIERS.md).\n')
 for c in chapters:guide.append('\n<a id="%s"></a>\n\n## %s\n\n%s\n'%(c['id'].replace('_','-'),c['title'],'\n\n'.join(c['paragraphs'])))
 yield ROOT/'docs/FIELD_GUIDE.md',''.join(guide)
if __name__=='__main__':
 import sys
 stale=[]
 for path,content in generate():
  if '--check' in sys.argv:
   if not path.exists() or path.read_text(encoding="utf-8")!=content:stale.append(str(path.relative_to(ROOT)))
  else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding="utf-8")
 if stale:raise SystemExit('Stale generated files: '+', '.join(stale))
 print('Validated 100 ordinary + 10 Nether-exclusive + 10 End-exclusive modifiers.')
